+func (t *Tofu) targets() []string {
+	if len(t.TargetValues) > 0 {
+		return t.TargetValues
+	}
+
+	if values, ok := t.Targets.([]string); ok {
+		return values
+	}
+
+	v := reflect.ValueOf(t.Targets)
+	if v.Kind() == reflect.Struct {
+		field := v.FieldByName("slice")
+		if field.IsValid() && field.Kind() == reflect.Slice {
+			values := make([]string, 0, field.Len())
+			for i := range field.Len() {
+				values = append(values, field.Index(i).String())
+			}
+
+			return values
+		}
+	}
+
+	return nil
+}
